258:     /**
259:      *
260:      *
261:      * @since    1.0.0
262:      */
263:     public function venipak_shipping_dispatch_order($order_ids, $packs, $is_global) {
264:         $url = 'https://go.venipak.lt/import/send.php';
265: 
266:         // Retry offsets: 0 (first try), then +1, +5, +10 if pack numbers collide
267:         $retry_offsets = array( 0, 1, 5, 10 );
268:         $result_xml_string = '';
269: 
270:         foreach ( $retry_offsets as $offset ) {
271:             if ( $offset > 0 ) {
272:                 // Bump the pack number counter before retrying
273:                 $this->settings->reserve_pack_numbers( $offset );
274:             }
275: 
276:             $xml = $this->getImportXML( $order_ids, $packs, $is_global );
277:             if ( ! $xml ) return null;
278: 
279:             $body = array( 'user' => $this->venipak_username, 'pass' => $this->venipak_password, 'xml_text' => $xml );
280:             $args = array(
281:                 'body'    => $body,
282:                 'timeout' => 45,
283:                 'headers' => array(
284:                     'Referer' => 'https://woocommerce.com/',
285:                 ),
286:             );
287:             $response = wp_remote_post( $url, $args );
288:             $result_xml_string = wp_remote_retrieve_body( $response );
289: 
290:             // Success — break out of retry loop
291:             if ( strpos( $result_xml_string, 'type="ok"' ) !== false || $result_xml_string === '' ) {
292:                 break;
293:             }
294: 
295:             // Only retry if the error is about pack number being in use
296:             if ( stripos( $result_xml_string, 'is already in use' ) === false ) {
297:                 break;
298:             }
299:         }
300: 
301:         if (strpos($result_xml_string, 'type="ok"') !== false || $result_xml_string === '') {
302:             foreach ($order_ids as $order_id) {
303:                 $order = wc_get_order( $order_id );
304:                 if (!$this->venipak_is_status_change_disabled)  {
305:                     $order->update_status('completed', __( 'Order dispatched to Venipak', 'woocommerce-shopup-venipak-shipping' ));
306:                 }
307: 
308:                 $venipak_shipping_order_data = json_decode($order->get_meta('venipak_shipping_order_data', true), true);
309:                 $venipak_shipping_order_data['status'] = 'sent';
310:                 $venipak_shipping_order_data['error_message'] = '';
311:                 $order->update_meta_data('venipak_shipping_order_data', json_encode($venipak_shipping_order_data));
312:                 $order->save();
313:             }
314:             return array('status' => 'ok', 'data' => $venipak_shipping_order_data);
315:         } else {
316:             $order = wc_get_order( $order_ids[0] );
317:             $venipak_shipping_order_data = json_decode($order->get_meta('venipak_shipping_order_data', true), true);
318:             $venipak_shipping_order_data['status'] = 'error';
319:             $venipak_shipping_order_data['error_message'] = strip_tags($result_xml_string);
320:             $order->update_meta_data('venipak_shipping_order_data', json_encode($venipak_shipping_order_data));
321:             $order->save();
322:             return array('status' => 'error', 'data' => $venipak_shipping_order_data['error_message']);
323:         }
324:     }
